    /**
     * Expected 5x5 covariance matrix produced by R for {@link #SWISS_DATA},
     * stored row-major.
     */
    private static final double[] EXPECTED_COVARIANCE = new double[] {
         156.0424976873265,  100.1691489361702,  -64.36692876965772,  -79.7295097132285,   241.5632030527289,
         100.169148936170251, 515.7994172062905, -124.39283071230344, -139.6574005550416,   379.9043755781684,
         -64.3669287696577,  -124.3928307123034,   63.64662349676226,   53.5758556891767,  -190.5606105457909,
         -79.7295097132285,  -139.6574005550416,   53.57585568917669,   92.4560592044403,   -61.6988297872340,
         241.5632030527289,   379.9043755781684, -190.56061054579092,  -61.6988297872340,  1739.2945371877890
    };

    /** Builds a matrix by reshaping a row-major flat array into {@code nRows x nCols}. */
    private static RealMatrix toMatrix(double[] data, int nRows, int nCols) {
        double[][] matrixData = new double[nRows][nCols];
        int offset = 0;
        for (int row = 0; row < nRows; row++) {
            System.arraycopy(data, offset, matrixData[row], 0, nCols);
            offset += nCols;
        }
        return new Array2DRowRealMatrix(matrixData);
    }

    /**
     * The covariance matrix of the Swiss fertility dataset should match the
     * reference values computed by R, within {@link #TOLERANCE}.
     */
    @Test
    public void testSwissFertility() {
        RealMatrix observations = toMatrix(SWISS_DATA, OBSERVATIONS, VARIABLES);
        RealMatrix actualCovariance = new Covariance(observations).getCovarianceMatrix();
        RealMatrix expectedCovariance = toMatrix(EXPECTED_COVARIANCE, VARIABLES, VARIABLES);

        TestUtils.assertEquals("covariance matrix", expectedCovariance, actualCovariance, TOLERANCE);
    }
}
